package org.apache.commons.jxpath.ri.model.beans;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.jxpath.JXPathContext;
import org.apache.commons.jxpath.JXPathInvalidAccessException;
import org.apache.commons.jxpath.ri.QName;
import org.apache.commons.jxpath.ri.model.NodePointer;
import org.apache.commons.jxpath.ri.model.QName;
import org.apache.commons.jxpath.ri.model.beans.PropertyOwnerPointer;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class NullPropertyPointer_createPath_TriageGen2Test {

    private JXPathContext mockContext;
    private NodePointer mockParent;
    private QName mockQName;

    @Before
    public void setUp() {
        mockContext = mock(JXPathContext.class);
        mockParent = mock(NodePointer.class);
        mockQName = mock(QName.class);
    }

    /**
     * Test Case 1: isAttribute() is true.
     * Tests the branch where the pointer is an attribute.
     */
    @Test
    public void testCreatePath_IsAttribute() {
        // Arrange
        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(mockParent));
        Object testValue = "testValue";
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockAttributePointer = mock(NodePointer.class);

        doReturn(true).when(nullPropertyPointer).isAttribute();
        when(nullPropertyPointer.getName()).thenReturn(mockQName);
        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createAttribute(mockContext, mockQName)).thenReturn(mockAttributePointer);

        // Act
        NodePointer result = nullPropertyPointer.createPath(mockContext, testValue);

        // Assert
        verify(mockNewParent).createAttribute(mockContext, mockQName);
        verify(mockAttributePointer).setValue(testValue);
        assertEquals(mockAttributePointer, result);
    }

    /**
     * Test Case 2: isAttribute() is false, and newParent is NOT a PropertyOwnerPointer.
     * Tests the branch for standard child creation.
     */
    @Test
    public void testCreatePath_IsNotAttribute_NotPropertyOwnerPointer() {
        // Arrange
        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(mockParent));
        Object testValue = "childValue";
        NodePointer mockNewParent = mock(NodePointer.class);
        NodePointer mockChildPointer = mock(NodePointer.class);

        doReturn(false).when(nullPropertyPointer).isAttribute();
        when(nullPropertyPointer.getName()).thenReturn(mockQName);
        when(mockParent.createPath(mockContext)).thenReturn(mockNewParent);
        when(mockNewParent.createChild(eq(mockContext), eq(mockQName), any(Integer.class), eq(testValue)))
                .thenReturn(mockChildPointer);

        // Setting index via reflection or assuming it's 0 if not specified, 
        // but we use any(Integer.class) to be safe or match internal state.
        // Since we can't easily set index if it's private, we rely on the mock behavior.

        // Act
        NodePointer result = nullPropertyPointer.createPath(mockContext, testValue);

        // Assert
        verify(mockNewParent).createChild(eq(mockContext), eq(mockQName), any(Integer.class), eq(testValue));
        assertEquals(mockChildPointer, result);
    }

    /**
     * Test Case 3: isAttribute() is false, and newParent IS a PropertyOwnerPointer.
     * Tests the branch where the parent is converted to a property pointer.
     */
    @Test
    public void testCreatePath_IsNotAttribute_IsPropertyOwnerPointer() {
        // Arrange
        NullPropertyPointer nullPropertyPointer = spy(new NullPropertyPointer(mockParent));
        Object testValue = "grandChildValue";

        PropertyOwnerPointer mockPop = mock(PropertyOwnerPointer.class);
        NodePointer mockPropertyPointer = mock(NodePointer.class);
        NodePointer mockChildPointer = mock(NodePointer.class);

        doReturn(false).when(nullPropertyPointer).isAttribute();
        when(nullPropertyPointer.getName()).thenReturn(mockQName);
        when(mockParent.createPath(mockContext)).thenReturn(mockPop);
        when(mockPop.getPropertyPointer()).thenReturn(mockPropertyPointer);
        when(mockPropertyPointer.createChild(eq(mockContext), eq(mockQName), any(Integer.class), eq(testValue)))
                .thenReturn(mockChildPointer);

        // Act
        NodePointer result = nullPropertyPointer.createPath(mockContext, testValue);

        // Assert
        verify(mockPop).getPropertyPointer();
        verify(mockPropertyPointer).createChild(eq(mockContext), eq(mockQName), any(Integer.class), eq(testValue));
        assertEquals(mockChildPointer, result);
    }
}
